'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const motion=matchMedia('(prefers-reduced-motion: reduce)');
const TRACKS=['Blockchain','DeFi','DAOs','GameFi','Security','Enterprise','NFTs'];
let selected=new Set(), expandedSpeakers=false, currentRole='builders', toastTimer;
try{const stored=JSON.parse(localStorage.getItem('carnival-interests')||'[]');if(Array.isArray(stored))selected=new Set(stored.filter(t=>TRACKS.includes(t)));document.body.classList.toggle('light',localStorage.getItem('carnival-scrapbook-theme')!=='dark');}catch{}
function savePreferences(){try{localStorage.setItem('carnival-interests',JSON.stringify([...selected]));localStorage.setItem('carnival-scrapbook-theme',document.body.classList.contains('light')?'light':'dark');}catch{}}
function toast(message){clearTimeout(toastTimer);$('.toast').textContent=message;$('.toast').classList.add('visible');toastTimer=setTimeout(()=>$('.toast').classList.remove('visible'),2600);}
function renderInterests(){
  $$('.track').forEach(b=>{const active=selected.has(b.dataset.track);b.setAttribute('aria-pressed',String(active));b.querySelector('.track-add').textContent=active?'✓':'+';});
  for(const target of ['.stamp-area','#registration-stamps']){const area=$(target);area.replaceChildren();if(selected.size){for(const name of selected){const stamp=document.createElement('span');stamp.className='stamp';stamp.textContent=name.toUpperCase();area.append(stamp);}}else if(target==='.stamp-area'){const p=document.createElement('p');p.textContent='Select a track to make this passport yours.';area.append(p);}}
  $('#interest-count').textContent=`${selected.size} interest${selected.size===1?'':'s'} selected`;
  $('#clear-tracks').hidden=!selected.size;$('#passport-dock').hidden=!selected.size;$('#dock-count').textContent=selected.size;savePreferences();
}
$$('.track').forEach(b=>b.addEventListener('click',()=>{const name=b.dataset.track;if(selected.has(name)){selected.delete(name);toast(`${name} removed from your passport`);}else{selected.add(name);toast(`${name} stamped into your passport`);}renderInterests();}));
$('#clear-tracks').addEventListener('click',()=>{selected.clear();renderInterests();toast('Your passport is ready for a fresh start');});
function updateThemeLabel(){$('.theme-toggle').setAttribute('aria-label',document.body.classList.contains('light')?'Switch to dark theme':'Switch to light theme');}
$('.theme-toggle').addEventListener('click',()=>{document.body.classList.toggle('light');updateThemeLabel();savePreferences();});updateThemeLabel();
function closeMenu(){$('#mobile-nav').hidden=true;$('.menu-toggle').setAttribute('aria-expanded','false');$('.menu-toggle').setAttribute('aria-label','Open navigation');}
$('.menu-toggle').addEventListener('click',()=>{const menu=$('#mobile-nav');menu.hidden=!menu.hidden;$('.menu-toggle').setAttribute('aria-expanded',String(!menu.hidden));$('.menu-toggle').setAttribute('aria-label',menu.hidden?'Open navigation':'Close navigation');});
$$('#mobile-nav a').forEach(a=>a.addEventListener('click',closeMenu));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#mobile-nav').hidden){closeMenu();$('.menu-toggle').focus();}});
$$('dialog').forEach(dialog=>{dialog.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});});
const speakers={
 raj:{name:'Raj Kapoor',role:'Founder, India Blockchain Alliance & Founder, Web3 On The Sea',location:'India',image:'raj.png',linkedin:'https://www.linkedin.com/in/indieblock'},
 nadja:{name:'Nadja Bester',role:'Co-founder, AdLunam. Documentary executive producer and host of The Future of NFTs.',location:'Dubai',image:'nadja.png',linkedin:'https://www.linkedin.com/in/nadjabester'},
 ajeet:{name:'Ajeet Khurana',role:'Angel investor; former CEO, Zebpay',location:'Dubai, UAE',image:'ajeet.png',linkedin:'https://www.linkedin.com/in/ajeetkhurana'},
 astha:{name:'Astha Yadav',role:'Senior Blockchain Developer, OCBC Bank & ZK Advocate',location:'Singapore',image:'astha.jpeg',linkedin:'https://www.linkedin.com/in/astha-yadav27'},
 vidhi:{name:'Vidhi Doshi',role:'Sr. Associate, Blockchain Founders Fund & Advisor, Stanford AI & Web3 & Member, Women in VC, NY',location:'India',image:'vidhi.jpg',linkedin:'https://www.linkedin.com/in/vidhi-doshi-118965134'},
 prashant:{name:'Prashant Kumar',role:'Head of Generative AI, Growth Markets, Accenture Song',location:'Malaysia',image:'prashant.jpeg',linkedin:'https://www.linkedin.com/in/prashantkumar2006'}
};
$$('.speaker-card').forEach(b=>b.addEventListener('click',()=>{const s=speakers[b.dataset.speaker];$('#profile-name').textContent=s.name;$('#profile-role').textContent=s.role;$('#profile-location').textContent=s.location;$('#profile-image').src=`assets/${s.image}`;$('#profile-image').alt=s.name;$('#profile-link').href=s.linkedin;$('#profile-dialog').showModal();}));
function filterSpeakers(){const query=$('#speaker-search').value.trim().toLowerCase();let count=0;$$('.speaker-card').forEach((card,i)=>{const visible=query?card.dataset.search.toLowerCase().includes(query):(expandedSpeakers||i<4);card.hidden=!visible;if(visible)count++;});$('#speaker-empty').hidden=!!count;$('#more-speakers').hidden=!!query;$('#more-speakers').textContent=expandedSpeakers?'Show fewer speakers −':'Explore more speakers +';}
$('#speaker-search').addEventListener('input',filterSpeakers);$('#more-speakers').addEventListener('click',()=>{expandedSpeakers=!expandedSpeakers;filterSpeakers();});filterSpeakers();
function updateRail(){const rail=$('.event-rail');$('#events-prev').disabled=rail.scrollLeft<2;$('#events-next').disabled=rail.scrollLeft+rail.clientWidth>=rail.scrollWidth-2;}
$$('.filter').forEach(b=>b.addEventListener('click',()=>{$$('.filter').forEach(f=>{f.classList.toggle('active',f===b);f.setAttribute('aria-pressed',String(f===b));});let count=0;$$('.event-card').forEach(c=>{c.hidden=b.dataset.location!=='all'&&c.dataset.eventLocation!==b.dataset.location;if(!c.hidden)count++;});$('#event-count').textContent=`${count} past event${count===1?'':'s'}`;$('.event-rail').scrollLeft=0;updateRail();}));
for(const [id,dir]of [['events-prev',-1],['events-next',1]])$('#'+id).addEventListener('click',()=>$('.event-rail').scrollBy({left:dir*(($('.event-card:not([hidden])')?.offsetWidth||322)+28),behavior:motion.matches?'instant':'smooth'}));
$('.event-rail').addEventListener('scroll',updateRail,{passive:true});window.addEventListener('resize',updateRail);updateRail();
const roles={builders:{mark:'{ }',heading:'Find your next “what if” people.',description:'Meet fellow developers, explore infrastructure and security, and connect with people turning ambitious ideas into working products.',tracks:['Blockchain','Security'],label:'builder'},founders:{mark:'↗',heading:'Your next chapter starts with a conversation.',description:'Find collaborators, meet investors and discover how the Web3 ecosystem can support your next venture. Bring the idea you cannot stop thinking about.',tracks:['Enterprise','DAOs'],label:'founder'},investors:{mark:'◈',heading:'Meet the people behind the possibility.',description:'Explore emerging ideas, connect with founders and join conversations on decentralised finance and real-world adoption.',tracks:['DeFi','Enterprise'],label:'investor'},curious:{mark:'✳',heading:'Curiosity is your only prerequisite.',description:'Discover digital ownership, gaming and community-led organisations. Meet welcoming people and find the corner of Web3 that speaks to you.',tracks:['NFTs','GameFi','DAOs'],label:'explorer'}};
function setRole(name,focus=false){currentRole=name;const r=roles[name];$$('[data-role]').forEach(b=>{const active=b.dataset.role===name;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;if(active&&focus)b.focus();});$('#role-panel').setAttribute('aria-labelledby','tab-'+name);$('.role-mark').textContent=r.mark;$('#role-panel h3').textContent=r.heading;$('#role-description').textContent=r.description;$('#role-route').textContent=`Add the ${r.label} route +`;}
$$('[data-role]').forEach(b=>{b.addEventListener('click',()=>setRole(b.dataset.role));b.addEventListener('keydown',e=>{const keys=Object.keys(roles),i=keys.indexOf(currentRole);let n;if(['ArrowDown','ArrowRight'].includes(e.key))n=(i+1)%keys.length;if(['ArrowUp','ArrowLeft'].includes(e.key))n=(i+keys.length-1)%keys.length;if(e.key==='Home')n=0;if(e.key==='End')n=keys.length-1;if(n!==undefined){e.preventDefault();setRole(keys[n],true);}});});
$('#role-route').addEventListener('click',()=>{roles[currentRole].tracks.forEach(t=>selected.add(t));renderInterests();toast('Your recommended route is in your passport');});
let chosenRole='';
$('#registration-step-two h2').id='details-heading';
function setStep(n){$('#registration-step-one').hidden=n!==1;$('#registration-step-one').disabled=n!==1;$('#registration-step-two').hidden=n!==2;$('#registration-step-two').disabled=n!==2;$('#registration-form').hidden=n===3;$('#registration-success').hidden=n!==3;$$('.step-indicator>span').forEach((s,i)=>s.classList.toggle('active',i<n));$('#registration-dialog').setAttribute('aria-labelledby',n===3?'success-heading':n===2?'details-heading':'registration-heading');}
function resetRegistration(){$('#registration-form').reset();chosenRole='';$('#role-error').hidden=true;setStep(1);$('#success-name').textContent='';$('#success-description').textContent='';$('#success-role').textContent='';$('#success-interests').textContent='';$('#enquire-passport').removeAttribute('href');}
function openRegistration(){closeMenu();resetRegistration();$('#registration-dialog').showModal();}
$$('.join-button').forEach(b=>b.addEventListener('click',openRegistration));$('#passport-dock').addEventListener('click',openRegistration);
$('#registration-next').addEventListener('click',()=>{const role=$('input[name=role]:checked');if(!role){$('#role-error').hidden=false;$('input[name=role]').focus();return;}chosenRole=role.value;$('#role-error').hidden=true;setStep(2);$('#guest-name').focus();});
$('#registration-back').addEventListener('click',()=>{setStep(1);$('input[name=role]:checked')?.focus();});
$('#registration-form').addEventListener('submit',e=>{e.preventDefault();const name=$('#guest-name').value.trim();if(!name){$('#guest-name').setCustomValidity('Please enter your name.');$('#guest-name').reportValidity();return;}$('#guest-name').setCustomValidity('');if(!$('#registration-form').reportValidity())return;$('#success-name').textContent=name;$('#success-role').textContent=chosenRole+' · Carnival Passport';$('#success-interests').textContent=selected.size?[...selected].join(' · '):'Open to all seven worlds';$('#success-description').textContent=`Welcome, ${name}. Here’s your starting point for the Carnival.`;const body=`Hello Web3 Carnival team,\n\nI would like to learn about the next edition.\n\nName: ${name}\nEmail: ${$('#guest-email').value}\nI am joining as a: ${chosenRole}\nInterests: ${selected.size?[...selected].join(', '):'All tracks'}\n\nPlease share dates, location and registration information when available.\n\nThank you!`;$('#enquire-passport').href='mailto:contact@threewaystudio.world?subject='+encodeURIComponent('Web3 Carnival next edition enquiry')+'&body='+encodeURIComponent(body);setStep(3);$('#download-passport').focus();});
$('#guest-name').addEventListener('input',()=>$('#guest-name').setCustomValidity(''));
$('#download-passport').addEventListener('click',()=>{const text=`WEB3 CARNIVAL\nYOUR PERSONAL CARNIVAL PASSPORT\n\n${$('#success-name').textContent}\n${chosenRole}\n\nYOUR INTERESTS\n${selected.size?[...selected].map(t=>'• '+t).join('\n'):'Open to all seven worlds'}\n\nNEXT EDITION\nDates and location: To be announced\n\nThis is a personal discovery plan from an independent redesign prototype. It is not a ticket, confirmed registration, NFT or booking. No information has been sent to the organisers.\n\nOfficial website: https://www.web3carnival.world/\nContact: contact@threewaystudio.world\n`;const blob=new Blob([text],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='my-carnival-passport.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your personal passport is downloading');});
$('#restart-registration').addEventListener('click',resetRegistration);$('#registration-dialog').addEventListener('close',resetRegistration);
$('#privacy-button').addEventListener('click',()=>$('#privacy-dialog').showModal());$('#clear-local-data').addEventListener('click',()=>{selected.clear();document.body.classList.add('light');updateThemeLabel();renderInterests();try{localStorage.removeItem('carnival-interests');localStorage.removeItem('carnival-theme');localStorage.removeItem('carnival-scrapbook-theme');}catch{}toast('Saved interests and theme cleared');});
renderInterests();
ScrollCraft.mount(document.body);
// Additive pointer depth: no pointer lock/capture and no continuous render loop.
const composition=$('.hero-composition');
if(matchMedia('(hover:hover) and (pointer:fine)').matches){$('.hero').addEventListener('pointermove',e=>{if(motion.matches)return;const r=$('.hero').getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;composition.style.transform=`translate(${x*12}px,${y*8}px)`;$('.hero-spark').style.transform=`rotate(${x*22}deg)`;});$('.hero').addEventListener('pointerleave',()=>{composition.style.transform='';$('.hero-spark').style.transform='';});}
